import React from "react";
import { useNavigate } from "react-router-dom";
import "./IncomeCategory.css";

function IncomeCategory({ onNext }) {
  const navigate = useNavigate();

  const categories = [
    {
      name: "Fixed Income",
      icon: "💼",
      desc: "Stable monthly salary"
    },
    {
      name: "Variable Income",
      icon: "📊",
      desc: "Income changes month to month"
    },
    {
      name: "Freelancer / Gig",
      icon: "🧑‍💻",
      desc: "Project based earnings"
    },
    {
      name: "Business Owner",
      icon: "🏢",
      desc: "Own business income"
    },
    {
      name: "Multiple Sources",
      icon: "🔀",
      desc: "More than one income stream"
    },
    {
      name: "No Income",
      icon: "🚫",
      desc: "Currently not earning"
    }
  ];

  const handleSelect = (category) => {
    if (onNext) {
      onNext(category);
    }
    navigate("/questionnaire");
  };

  return (
    <div className="income-container">
      <h1 className="income-title">Select Your Income Type</h1>
      <p className="income-subtitle">Choose the option that best describes you</p>

      <div className="income-grid">
        {categories.map((item) => (
          <div
            key={item.name}
            className="income-card"
            onClick={() => handleSelect(item.name)}
          >
            <div className="income-icon">{item.icon}</div>
            <div className="income-name">{item.name}</div>
            <div className="income-desc">{item.desc}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default IncomeCategory;
